using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using IdleRestaurant;
using UnityEngine;
using UnityEngine.EventSystems;
using TMPro;
public sealed class FreshAudio:MonoBehaviour{
 public volatile bool capturing;public int channels=2;readonly object sync=new object();readonly List<float> samples=new List<float>();
 void OnAudioFilterRead(float[] data,int count){if(!capturing)return;lock(sync){channels=count;samples.AddRange(data);}}
 public void Begin(){lock(sync)samples.Clear();capturing=true;}
 public int End(string p){capturing=false;lock(sync){var a=samples.ToArray();var b=new byte[a.Length*4];Buffer.BlockCopy(a,0,b,0,b.Length);File.WriteAllBytes(p,b);return a.Length;}}
}
public static class FreshSession{
 static readonly string Root=Path.GetFullPath("Recordings/FreshSession051");
 static RestaurantApp app;static FreshAudio audio;static double start;static float wall;static string error="";static int purchases;static readonly List<object> events=new List<object>(),segments=new List<object>(),samples=new List<object>();static readonly List<string> checks=new List<string>();
 static double Elapsed=>app.Game.State.seconds-start;
 static void Note(string kind,object detail=null){events.Add(new{kind,seconds=Elapsed,wallSeconds=Time.realtimeSinceStartup-wall,cash=app.Game.State.cash,tickets=app.Game.State.gems,outlet=app.Game.State.selected,managers=app.Game.TeamCount,waves=app.Game.TotalWaves(),detail});Flush();}
 static void Flush(){File.WriteAllText(Path.Combine(Root,"session-live.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{running=true,seconds=Elapsed,wallSeconds=Time.realtimeSinceStartup-wall,frame=Time.frameCount,cash=app.Game.State.cash,income=app.Game.NetworkIncome(),outlets=app.Game.State.outlets.Count(x=>x.open),managers=app.Game.TeamCount,waves=app.Game.TotalWaves(),purchases,events,samples},Newtonsoft.Json.Formatting.Indented));}
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);checks.Add(text);}
 public static void Main(){app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();if(!Application.isPlaying||!app)throw new Exception("Play restaurant first");app.StartCoroutine(Guard(Run()));}
 static IEnumerator Guard(IEnumerator root){var stack=new Stack<IEnumerator>();stack.Push(root);try{while(stack.Count>0){object current=null;bool next=false;try{next=stack.Peek().MoveNext();if(next)current=stack.Peek().Current;}catch(Exception ex){error=ex.ToString();File.WriteAllText(Path.Combine(Root,"error.txt"),error);break;}if(!next){(stack.Pop() as IDisposable)?.Dispose();continue;}if(current is IEnumerator iter){stack.Push(iter);continue;}yield return current;}}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();}}
 static bool Tap(GameObject go){if(!go)throw new Exception("Missing tap target");var b=go.GetComponent<UnityEngine.UI.Button>();if(!b||!b.interactable)throw new Exception("Disabled "+go.name);Canvas.ForceUpdateCanvases();var r=(RectTransform)b.transform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()!=b)throw new Exception("Blocked "+go.name);ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerClickHandler);return true;}
 static void Tap(string name)=>Tap(GameObject.Find(name));
 static void TextTap(string label)=>Tap(UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Button>(FindObjectsSortMode.None).First(b=>b.isActiveAndEnabled&&b.GetComponentInChildren<TMP_Text>().text==label).gameObject);
 static IEnumerator Shot(string name){yield return new WaitForEndOfFrame();var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Root,name+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
 static IEnumerator Record(string id,string title,float seconds,Action<float> step=null){string folder=Path.Combine(Root,"raw",id);Directory.CreateDirectory(folder);var frames=new List<object>();int n=0;float began=Time.realtimeSinceStartup;double from=Elapsed;audio.Begin();while(Time.realtimeSinceStartup-began<seconds){step?.Invoke(Time.realtimeSinceStartup-began);yield return new WaitForEndOfFrame();var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);t.Apply();string file=(n++).ToString("D4")+".jpg";File.WriteAllBytes(Path.Combine(folder,file),t.EncodeToJPG(88));UnityEngine.Object.Destroy(t);frames.Add(new{file,seconds=Time.realtimeSinceStartup-began,frame=Time.frameCount});yield return new WaitForSecondsRealtime(.04f);}float duration=Time.realtimeSinceStartup-began;int count=audio.End(Path.Combine(folder,"audio.f32"));File.WriteAllText(Path.Combine(folder,"frames.json"),Newtonsoft.Json.JsonConvert.SerializeObject(frames));segments.Add(new{id,title,duration,frames=n,audioSamples=count,channels=audio.channels,sampleRate=AudioSettings.outputSampleRate,sessionSeconds=from});File.WriteAllText(Path.Combine(Root,"segments.json"),Newtonsoft.Json.JsonConvert.SerializeObject(segments,Newtonsoft.Json.Formatting.Indented));}
 static IEnumerator Buy(int card){yield return new WaitForSecondsRealtime(.15f);TextTap(new[]{"ORDERS","KITCHEN","DINING"}[card/3]);yield return new WaitForSecondsRealtime(.1f);int before=app.Game.State.outlets[app.Game.State.selected].upgrades[card];Tap("Upgrade "+card);Check(app.Game.State.outlets[app.Game.State.selected].upgrades[card]==before+1,"Upgrade tap bought card "+card);purchases++;Note("upgrade",new{card,level=before+1});}
 static IEnumerator Goals(){app.Navigate("tasks");yield return new WaitForSecondsRealtime(.2f);for(int i=0;i<12;i++){if(app.Game.GoalClaimed(i)||app.Game.GoalProgress(i)<app.Game.GoalTarget(i))continue;var row=GameObject.Find("Goal row "+i);var scroll=row.GetComponentInParent<UnityEngine.UI.ScrollRect>();Canvas.ForceUpdateCanvases();float target=i*180-80;scroll.content.anchoredPosition=new Vector2(0,Mathf.Clamp(target,0,Mathf.Max(0,scroll.content.rect.height-scroll.viewport.rect.height)));yield return new WaitForSecondsRealtime(.12f);Tap("Goal claim "+i);Note("goal claimed",i);}app.Navigate("play");yield return null;}
 static IEnumerator Run(){Directory.CreateDirectory(Root);string original=Newtonsoft.Json.JsonConvert.SerializeObject(app.Game.State);bool complete=false;audio=app.gameCamera.gameObject.AddComponent<FreshAudio>();try{
 app.Game.State=new RestaurantGame(app.catalog).State;app.Navigate("play");app.world.Show(0);typeof(RestaurantApp).GetMethod("TutorialDialog",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(app,null);app.Save();start=app.Game.State.seconds;wall=Time.realtimeSinceStartup;Check(app.Game.State.cash==0&&app.Game.TeamCount==0&&app.Game.State.outlets.Count(o=>o.open)==1,"Fresh zero-resource save, one restaurant, no managers");Note("fresh start");
 var a=app.world.room.GetComponent<RestaurantAtmosphere>();Check(a.CornerFixtures==4&&a.HangingFixtures==9&&a.Candles==6&&a.LitCandles==0&&a.EnabledLights==0,"Four corner lamps, nine counter pendants and six unlit daytime candles");for(int i=0;i<3;i++){var shade=app.world.room.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name=="Counter shade "+i);Check(shade&&Mathf.Abs(shade.localPosition.x-RestaurantWorld.CounterPosition(i).x)<.001f,"Counter "+i+" is centred under its shade");}bool opened=false;yield return Record("01-welcome","Fresh save - opening the restaurant",4,t=>{if(t>1.5f&&!opened){opened=true;TextTap("OPEN MY RESTAURANT");}});
 bool night=false,day=false,trained=false;int waves=0,openedCount=1,recruits=0;double nextSample=30,nextGoal=60;float decisionAt=Time.realtimeSinceStartup;
 while(Elapsed<1500){
  if(app.Game.Guide==2){yield return new WaitForSecondsRealtime(.8f);yield return Buy(0);}else if(app.Game.Guide==3){yield return new WaitForSecondsRealtime(.8f);yield return Buy(3);}else if(app.Game.Guide==5){yield return new WaitForSecondsRealtime(.8f);TextTap("MAP");yield return new WaitForSecondsRealtime(.3f);Note("tutorial completed");yield return Shot("tutorial-map");app.Navigate("play");}
  a=app.world.room.GetComponent<RestaurantAtmosphere>();if(!night&&a.NightAmount>.99f){night=true;Check(a.LitCandles==6&&a.EnabledLights==13,"Night lights all three counters and six table candles");yield return Record("02-night","First earned service - candles lit at night",6);yield return Shot("night-candles");}
  if(night&&!day&&app.Game.State.outlets[0].waves>=2&&a.NightAmount<.01f){day=true;Check(a.LitCandles==0&&a.EnabledLights==0,"Following service extinguishes candles and lamps in daylight");Note("day returned");}
  if(app.Game.TotalWaves()!=waves){waves=app.Game.TotalWaves();Note("service complete");}
  if(Elapsed>=nextSample){samples.Add(new{seconds=Elapsed,cash=app.Game.State.cash,income=app.Game.NetworkIncome(),outlets=app.Game.State.outlets.Count(o=>o.open),managers=app.Game.TeamCount,waves,purchases,forecast=app.Game.State.outlets[app.Game.State.selected].incomeCalibration});nextSample+=30;Flush();}
  if(app.Game.State.introComplete&&Time.realtimeSinceStartup>=decisionAt){decisionAt=Time.realtimeSinceStartup+2;
   int current=app.Game.State.selected,next=current+1;
   if(app.Game.TeamCount>0&&app.Game.State.outlets[current].managers[0]!=0){app.Navigate("managers");yield return new WaitForSecondsRealtime(.3f);bool assigned=false;yield return Record("03-starter-"+current,"Earned teammate - assign to Orders",6,t=>{if(t>2&&!assigned){assigned=true;Tap("Assign manager 0");Check(app.Game.State.outlets[current].managers[0]==0,"Earned starter can be assigned before restaurant 2");Note("starter assigned");}});app.Navigate("play");yield return new WaitForSecondsRealtime(.2f);continue;}
   if(next<40&&app.Game.CanOpen(next,out _)){app.Navigate("map");yield return new WaitForSecondsRealtime(.3f);bool tapped=false;yield return Record(next==1?"03-outlet-two":"05-outlet-three","Earned opening - "+app.catalog.outlets[next].title,6,t=>{if(t>2&&!tapped){tapped=true;Tap("Map outlet action "+next);Note("restaurant opened",new{number=next+1,title=app.catalog.outlets[next].title});}});openedCount++;if(next==1){app.Navigate("managers");yield return new WaitForSecondsRealtime(.2f);Tap("Assign manager 0");Note("free starter assigned");app.Navigate("play");}continue;}
   if(app.Game.CanRecruit(out _)){app.Navigate("managers");yield return new WaitForSecondsRealtime(.3f);int m=app.Game.TeamCount,id=app.Game.NextRecruitId();bool tapped=false,assignedNew=false;yield return Record("04-team-"+recruits,"Earned tickets - welcome one teammate",6,t=>{if(t>2&&!tapped){tapped=true;Tap("Welcome next manager");Check(app.Game.TeamCount==m+1,"Welcome grants one teammate");Note("manager welcomed",new{name=app.catalog.managers[id].title,role=app.catalog.managers[id].role});}if(t>4&&!assignedNew){assignedNew=true;Tap("Assign manager "+id);Note("manager assigned",id);}});recruits++;app.Navigate("play");continue;}
   if(app.Game.TeamCount>0&&!trained&&app.Game.State.gems>=3){app.Navigate("managers");yield return new WaitForSecondsRealtime(.3f);Tap("Train manager 0");trained=true;Note("starter trained");app.Navigate("play");continue;}
   if(Elapsed>=nextGoal){nextGoal=Elapsed+60;yield return Goals();continue;}
   bool mustInvest=next<40&&app.Game.OutletUpgradeCount(current)<app.Game.OutletUpgradesRequired(next);bool banking=next<40&&app.Game.ExpansionReady(next,out _)&&app.Game.State.cash>app.Game.FamilyUnlock(next)*.65;double before=app.Game.FamilyIncome(current),best=0;int chosen=-1;
   if(!banking)for(int c=0;c<9;c++){double cost=app.Game.Cost(current,c);if(!double.IsFinite(cost)||cost>app.Game.State.cash)continue;app.Game.State.outlets[current].upgrades[c]++;double gain=(app.Game.FamilyIncome(current)-before)/60;app.Game.State.outlets[current].upgrades[c]--;double roi=gain/cost;if(roi>best&&(roi>1.0/300||mustInvest)){best=roi;chosen=c;}}
   if(chosen>=0)yield return Buy(chosen);
  }
  if(Elapsed>=1200&&openedCount>=3&&app.Game.TeamCount>=3)break;
  yield return null;
 }
 Check(app.Game.State.outlets[1].open,"Second restaurant unlocked with naturally earned cash and milestones");Check(app.Game.TeamCount>=2,"Free starter plus at least one individually earned manager");Check(night&&day,"Day-night-day verified in the actual fresh session");yield return Record("06-session-end","Long session - earned progress",6);app.Save();File.WriteAllText(Path.Combine(Root,"earned-session-save.json"),Newtonsoft.Json.JsonConvert.SerializeObject(app.Game.State));complete=true;
 }finally{audio.capturing=false;UnityEngine.Object.Destroy(audio);File.WriteAllText(Path.Combine(Root,"FreshSessionVerification.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{utc=DateTime.UtcNow,status=complete?"PASS":"FAIL",error,gameSeconds=Elapsed,wallSeconds=Time.realtimeSinceStartup-wall,timeScale=Time.timeScale,cash=app.Game.State.cash,totalEarned=app.Game.State.totalEarned,outlets=app.Game.State.outlets.Count(o=>o.open),managers=app.Game.TeamCount,waves=app.Game.TotalWaves(),purchases,checks,events,samples,scope="Unaccelerated live Unity fresh save; actual UI taps; no seeded currency or milestone skips. Automatic upgrade choices and optional goal claims, no research or offline rewards."},Newtonsoft.Json.Formatting.Indented));app.Game.State=new RestaurantGame(app.catalog,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(original)).State;app.Navigate("play");app.world.Show(app.Game.State.selected);app.Save();File.WriteAllText(Path.Combine(Root,"status.txt"),complete?"COMPLETE":"FAILED "+error);}}
}
